const i = $input.first().json || {};
const ref = String(i.reference || '').toUpperCase().replace(/\s+/g, '').replace(/[^A-Z0-9-]/g, '');
const modele = String(i.modele || '').toUpperCase().replace(/\s+/g, '').replace(/[^A-Z0-9()\/-]/g, '');
const mots_cles = String(i.mots_cles || '').slice(0, 200);
const role = String(i.role || 'technicien').toLowerCase();
return [{ json: { ref, modele, mots_cles, role } }];

const e = $('Entree').first().json;
const h = String(($input.first().json || {}).html || '');
const rows = [];
const vus = new Set();
const re = /<tr class="componentsList__row[^"]*"([^>]*)>([\s\S]*?)<\/tr>/g;
let m;
while ((m = re.exec(h))) {
  const a = m[1];
  const g = n => { const x = new RegExp(n + '="([^"]*)"').exec(a); return x ? x[1] : ''; };
  const dm = /js-componentsList-description">([\s\S]*?)<\/span>/.exec(m[2]);
  const des = (dm ? dm[1] : '').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&#0?39;/g, "'").replace(/\s+/g, ' ').trim();
  const ref = g('data-id');
  if (!ref || vus.has(ref)) continue;
  vus.add(ref);
  const p = parseFloat(g('data-price'));
  rows.push({ ref, des, zt: g('data-zt'), repere: g('data-reference'), prix: isNaN(p) ? null : p });
}
if (!rows.length) return [{ json: { liste: true, vide: true, zt: '', lignes: [] } }];
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const syn = [
  [/VENTIL/, ['MOTEUR VENT', 'FAN MOTOR', 'MOTOR FAN', 'MOTEUR VENTIL', 'MOTOR, FAN']],
  [/HELICE|TURBINE/, ['PROPELLER', 'HELICE', 'TURBINE', 'FAN, PROPELLER', 'CROSS FLOW']],
  [/CARTE|ELECTRONIQUE|PCB|PWB/, ['CARTE', 'P.C. BOARD', 'PC BOARD', 'PCB', 'BOARD', 'INVERTER']],
  [/COMPRESS/, ['COMPRESSOR', 'COMPRESSEUR']],
  [/SONDE|CAPTEUR|THERMISTANCE/, ['SONDE', 'THERMISTOR', 'SENSOR', 'TEMP']],
  [/4 VOIES|VANNE 4|INVERSION/, ['4 VOIES', '4-WAY', 'REVERSING']],
  [/DETENDEUR|PMV/, ['PMV', 'DETENDEUR', 'EXPANSION', 'BOBINE PMV', 'COIL']],
  [/CONDENSATEUR/, ['CAPACITOR', 'CONDENSATEUR']],
  [/TELECOMMANDE/, ['TELECOMMANDE', 'REMOTE', 'CONTROLLER']],
  [/POMPE/, ['POMPE', 'PUMP']],
  [/VOLET/, ['VOLET', 'LOUVER', 'MOTEUR VOLETS']],
  [/PRESSOSTAT/, ['PRESSOSTAT', 'PRESSURE SWITCH']],
  [/FLOTTEUR/, ['FLOTTEUR', 'FLOAT']],
  [/FILTRE/, ['FILTRE', 'FILTER']],
  [/BAC/, ['BAC', 'DRAIN PAN']]
];
const demande = norm(e.mots_cles);
const kws = new Set(demande.split(/[,;\/]+/).map(s => s.trim()).filter(s => s.length >= 3));
for (const [r, l] of syn) if (r.test(demande)) l.forEach(k => kws.add(k));
const cands = rows.map(r => { const d = norm(r.des); let s = 0; for (const k of kws) if (d.includes(k)) s += k.length; return { r, s }; }).filter(x => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 5).map(x => x.r);
if (!cands.length) return [{ json: { liste: true, zt: '', lignes: rows.map(r => 'rep ' + r.repere + ' | ' + r.ref + ' | ' + r.des) } }];
return cands.map(c => ({ json: c }));

function tous(n) { try { return $(n).all().map(i => i.json); } catch (x) { return null; } }
const e = $('Entree').first().json;
const s = $('Selection').first().json;
const admin = e.role === 'admin';
const MARGE = 1.30;
const fmt = n => n.toFixed(2).replace('.', ',') + ' EUR';
if (s.etape === 'fin') return [{ json: { resultat: s.resultat } }];
const ps = s.etape === 'vue' ? (tous('Pieces') || []) : [s];
const st = $input.all().map(i => i.json || {});
const L = [];
if (s.etape === 'vue') L.push('Modele Toshiba ' + s.modele + (s.description ? ' (' + s.description + (s.unite ? ', ' + s.unite : '') + ')' : '') + '.');
if (ps.length && ps[0].liste) {
  if (ps[0].vide) L.push('Vue eclatee introuvable pour ce modele sur le portail Toshiba. Verifier sur pieces.toshiba-confort.fr.');
  else {
    L.push('Aucune piece ne correspond a : ' + e.mots_cles + '. Liste des pieces du modele (repere | reference | designation) :');
    ps[0].lignes.slice(0, 120).forEach(x => L.push(x));
    L.push('Choisis la bonne ligne et rappelle l outil avec sa reference exacte.');
  }
  return [{ json: { resultat: L.join('\n') } }];
}
L.push(s.etape === 'vue' ? 'Pieces correspondantes :' : 'Piece Toshiba :');
ps.forEach((p, i) => {
  const q = st[i] && typeof st[i].quantity === 'number' ? st[i].quantity : null;
  let v;
  if (q !== null && q > 0) v = 'En stock chez Toshiba France (' + q + ' disponibles)';
  else if (q === 0) v = 'Rupture de stock chez Toshiba France : demander le delai';
  else v = 'Disponibilite non lue, verifier sur pieces.toshiba-confort.fr';
  let l = '- ' + (p.des || 'Piece') + (p.repere ? ' (repere ' + p.repere + ')' : '') + ' : ' + p.ref + '. ' + v + '.';
  if (p.prix != null && p.prix > 0) {
    l += ' Prix indicatif client ' + fmt(Math.round(p.prix * MARGE * 100) / 100) + ' HT hors pose.';
    if (admin) l += ' Prix portail Toshiba (a afficher a Laurent) ' + fmt(p.prix) + '.';
  } else l += ' Prix non communique par le portail.';
  L.push(l);
});
L.push('Le portail Toshiba n indique pas les references de remplacement.');
L.push('Source : pieces.toshiba-confort.fr, ' + $now.setZone('Europe/Paris').toFormat('dd/MM/yyyy') + '.');
return [{ json: { resultat: L.join('\n') } }];

const e = $('Entree').first().json;
const raw = $input.first().json || {};
const d = Array.isArray(raw.aaData) ? raw.aaData : [];
const cle = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const prix = s => { const v = parseFloat(String(s || '').replace(/[^0-9,.]/g, '').replace(/\./g, '').replace(',', '.')); return isNaN(v) ? null : v; };
const unite = t => /^ZIU/.test(t) ? 'unite interieure' : (/^ZCDU/.test(t) ? 'groupe exterieur' : (/^ZESTIA/.test(t) ? 'ESTIA' : ''));
const fin = t => [{ json: { etape: 'fin', resultat: t } }];
if (!d.length) return fin('Impossible de lire le catalogue pieces.toshiba-confort.fr pour le moment. Verifier sur le site ou demander a Laurent.');
if (e.ref) {
  const r = d.find(x => cle(x[1]) === cle(e.ref));
  if (!r) {
    const p = d.filter(x => x[4] === 'ZSPARTS' && cle(x[1]).startsWith(cle(e.ref).slice(0, 6))).slice(0, 5).map(x => x[1] + ' (' + x[2] + ')');
    return fin('Reference ' + e.ref + ' introuvable sur pieces.toshiba-confort.fr.' + (p.length ? ' References proches : ' + p.join(', ') + '.' : ''));
  }
  return [{ json: { etape: 'stock', zt: r[0], ref: r[1], des: r[2], prix: prix(r[3]), repere: '' } }];
}
if (!e.modele) return fin('Ni reference de piece ni modele de machine : demander une photo de la plaque signaletique.');
const models = d.filter(x => x[4] !== 'ZSPARTS' && x[4] !== 'MISSING' && x[4] !== 'ZSERVICE');
const t = cle(e.modele);
const m = models.find(x => cle(x[1]) === t) || models.find(x => cle(x[1]).startsWith(t)) || models.find(x => cle(x[1]).length >= 8 && t.startsWith(cle(x[1])));
if (!m) {
  const p = models.filter(x => cle(x[1]).includes(t.slice(0, 7))).slice(0, 8).map(x => x[1]);
  return fin('Modele ' + e.modele + ' introuvable sur pieces.toshiba-confort.fr.' + (p.length ? ' Modeles proches : ' + p.join(', ') + '.' : '') + ' Verifier la plaque (unite interieure ou groupe exterieur).');
}
return [{ json: { etape: 'vue', modele: m[1], description: m[2], unite: unite(m[4]) } }];
